use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


// Reads OPENAI_API_KEY (and OPENAI_BASE_URL, if set).
let client = OpenAI::from_env()?;


let agent = AgentBuilder::new(client.completion(openai::GPT_5_5))
    .preamble("You are a helpful assistant.")
    .build();


let answer = agent.prompt("Hello!").await?.output();
println!("{answer}");

use rig::providers::openai::{OpenAI, OpenAIConfig};


// From OPENAI_API_KEY and the optional OPENAI_BASE_URL.
let client = OpenAI::from_env()?;


// From an explicit key.
let client = OpenAI::new("your-api-key");


// From a configuration, for anything beyond the key.
let client = OpenAIConfig::new("your-api-key")
    .with_base_url("https://your-gateway.example.com/v1")
    .client();

use rig::providers::openai::{self, OpenAI};


let client = OpenAI::from_env()?;


let responses = client.completion(openai::GPT_5_5); // Responses API
let chat = client.chat(openai::GPT_5_5);            // Chat Completions

use rig::providers::openai::{self, OpenAIConfig, Route};


let model = OpenAIConfig::from_env()?
    .with_route(Route::Chat)
    .client()
    .completion(openai::GPT_5_5);

use rig::completion::{CacheRetention, Effort, ServiceTier, Verbosity};
use rig::prelude::*;
use rig::providers::openai::{self, OpenAI};


let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .reasoning(Effort::High)          // reasoning.effort / reasoning_effort
    .cache(CacheRetention::Long)      // extended prompt-cache retention
    .service_tier(ServiceTier::Flex)  // service_tier
    .verbosity(Verbosity::Low)        // text.verbosity / verbosity
    .build();

use rig::prelude::*;
use rig::providers::openai::extension::{ChatOptions, OpenAiOptions, ReasoningSummary};
use rig::providers::openai::{self, OpenAI};


let options = OpenAiOptions::new()
    .store(false)
    .prompt_cache_key("support-bot")
    .reasoning_summary(ReasoningSummary::Auto)
    .chat(ChatOptions::new().logprobs(true));


let agent = AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
    .provider_option(options)
    .build();

use rig::completion::CompletionRequest;
use rig::providers::openai::extension::OpenAiExt;
use rig::providers::openai::{self, OpenAI};


let model = OpenAI::from_env()?.completion(openai::GPT_5_5);
let response = model.call(CompletionRequest::new("Name a prime number.")).await?;


println!("{}", response.text());
if let Some(Ok(extras)) = response.extras::<OpenAiExt>() {
    println!("served on tier {:?}", extras.service_tier);
}

use rig::providers::openai::{self, OpenAI};


let client = OpenAI::from_env()?;


// The model's default width...
let embedder = client.embedding(openai::TEXT_EMBEDDING_3_SMALL, None);
// ...or a shorter vector, for models that support `dimensions`.
let small = client.embedding(openai::TEXT_EMBEDDING_3_LARGE, Some(256));

use rig::completion::CompletionRequest;
use rig::providers::openai::{self, OpenAI};


let model = OpenAI::from_env()?.responses(openai::GPT_5_5);
let mut session = model.responses_websocket().connect().await?;


let first = session.completion(CompletionRequest::new("What is ownership in Rust?")).await?;
println!("{}", first.text());


// The session sends the previous response id for you.
let second = session.completion(CompletionRequest::new("And borrowing?")).await?;
println!("{}", second.text());


session.close().await?;
